#!/usr/bin/env python3
"""Author: Andrew Fisher. Rebuild the v7.90 explorer files from their exact live v7.82 inputs.
Usage: python3 patch_explorer790.py <live explorer.js> <live index.html> <output folder>
This writes local files only. It never uploads or modifies the shared record.
"""
import hashlib, pathlib, sys
sys.path.insert(0, str(pathlib.Path(__file__).resolve().parent.parent / 'toolchain'))
from rep import rep
base_js, base_index, out = map(pathlib.Path, sys.argv[1:4])
def read_guard(p, expected):
    b = p.read_bytes()
    if hashlib.sha256(b).hexdigest() != expected:
        sys.exit('Wrong base for ' + p.name + '; fetch current live files and review before rebuilding')
    return b.decode('utf-8')
src = read_guard(base_js, 'dd6256bcd3e20cd89a70ba1c1d32e5f3b7b1acf09a2d19f1ac824f05fea93d3e')
idx = read_guard(base_index, '634881d7832bfd4f892ec50ae1e7eacbce2ea8d37dc0479d22804f190e94095e')
rep(src, "function setMode(m) {\n  if (m === mode) return; mode = m; document.querySelectorAll('.modes button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.mode === m)));\n  dropVTQueue(); setSatState('');\n", "function setMode(m) {\n  if (m === mode) return; const wasGeo790 = geoOn(); mode = m; /* v7.90 - see below */ document.querySelectorAll('.modes button').forEach(b => b.setAttribute('aria-pressed', String(b.dataset.mode === m)));\n  dropVTQueue(); setSatState('');\n", 'v7.90 explorer change 1', str(base_js))
