digest = hashlib.sha256(src.encode('utf-8')).hexdigest()
idx = rep(idx, 'explorer.js?v=dd6256bcd3e20', 'explorer.js?v=' + digest[:12], 'version the explorer script', str(base_index))
out.mkdir(parents=True, exist_ok=True)
for name, text in [('explorer.js', src), ('index.html', idx)]:
    data = text.encode('utf-8'); (out / name).write_bytes(data)
    print(name, len(data), hashlib.sha256(data).hexdigest())
